class Solution {
public:
    string pushDominoes(string dominoes) {
        int n = dominoes.size();
        int i = -1; // virtual 'L' sentinel at position -1
        for (int j = 0; j < n; ++j) {
            if (dominoes[j] == '.') continue;
            char left  = (i == -1) ? 'L' : dominoes[i];
            char right = dominoes[j];
            if (left == right) {
                for (int k = i + 1; k < j; ++k) dominoes[k] = left;
            } else if (left == 'R' && right == 'L') {
                int lo = i + 1, hi = j - 1;
                while (lo < hi) {
                    dominoes[lo++] = 'R';
                    dominoes[hi--] = 'L';
                }
            }
            // left == 'L' && right == 'R': leave dots unchanged
            i = j;
        }
        // suffix: virtual 'R' sentinel at position n
        char left = (i == -1) ? 'L' : dominoes[i];
        if (left == 'R') {
            for (int k = i + 1; k < n; ++k) dominoes[k] = 'R';
        }
        return dominoes;
    }
};
